import{_ as e,o,c as l,af as d}from"./chunks/framework.BSym9njW.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"00-environment/npu-troubleshooting.md","filePath":"en/00-environment/npu-troubleshooting.md","lastUpdated":1789547203000}'),n={name:"00-environment/npu-troubleshooting.md"};function a(r,t,s,i,c,m){return o(),l("div",null,[...t[0]||(t[0]=[d('<h2 id="fastflowlm-lemonade-troubleshooting" tabindex="-1">FastFlowLM / Lemonade troubleshooting <a class="header-anchor" href="#fastflowlm-lemonade-troubleshooting" aria-label="Permalink to &quot;FastFlowLM / Lemonade troubleshooting&quot;">​</a></h2><p>Common NPU and Lemonade issues. For ROCm / HIP GPU problems, see <a href="/hello-rocm/00-environment/#3-verify-installation">00-Environment verification</a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Symptom</th><th style="text-align:left;">Fix</th></tr></thead><tbody><tr><td style="text-align:left;">No <code>flm</code></td><td style="text-align:left;">Follow <a href="./fastflowlm">FastFlowLM environment</a>, then <strong>reboot</strong></td></tr><tr><td style="text-align:left;"><code>No NPU device found</code></td><td style="text-align:left;">Check <code>/dev/accel/accel0</code> and <code>render</code> group; <code>sudo usermod -aG render,video $USER</code> then re-login</td></tr><tr><td style="text-align:left;">SVA bind <code>-19</code></td><td style="text-align:left;">cmdline must have <code>amd_iommu=on iommu=pt</code>; update GRUB and reboot</td></tr><tr><td style="text-align:left;"><code>No such device with index &#39;0&#39;</code></td><td style="text-align:left;">unset <code>ROCM_PATH HIP_PATH LD_LIBRARY_PATH</code>; check <code>xrt-smi examine</code></td></tr><tr><td style="text-align:left;">NPU gone after firmware-only swap</td><td style="text-align:left;">driver + firmware must match; use PPA <code>amdxdna-dkms</code></td></tr><tr><td style="text-align:left;"><code>modinfo amdxdna</code> not under <code>updates/dkms</code></td><td style="text-align:left;">no reboot yet, or still on in-tree module</td></tr><tr><td style="text-align:left;"><code>ulimit -l</code> not unlimited</td><td style="text-align:left;">write <code>limits.conf</code>, re-login</td></tr><tr><td style="text-align:left;">NPU vs large-GTT recipe</td><td style="text-align:left;">GTT often uses <code>amd_iommu=off</code>, incompatible with FLM</td></tr><tr><td style="text-align:left;">No <code>lemonade</code></td><td style="text-align:left;"><code>sudo apt install lemonade-server</code></td></tr><tr><td style="text-align:left;"><code>status</code> cannot reach 13305</td><td style="text-align:left;">process <code>/usr/bin/lemond</code>; <code>ss -tlnp | grep 13305</code>; <code>sudo systemctl start lemond</code></td></tr><tr><td style="text-align:left;">13305 will not stop</td><td style="text-align:left;"><code>sudo systemctl stop lemond</code> (unit is not lemonade-server)</td></tr><tr><td style="text-align:left;"><code>llamacpp:rocm</code> = kernel missing support</td><td style="text-align:left;">use <code>llamacpp:vulkan</code>; see <a href="https://lemonade-server.ai/gfx1151_linux.html" target="_blank" rel="noreferrer">gfx1151 Linux</a></td></tr><tr><td style="text-align:left;"><code>flm:npu</code> missing / GitHub timeout</td><td style="text-align:left;">use native <a href="./fastflowlm">FastFlowLM</a></td></tr><tr><td style="text-align:left;"><code>load gemma4-it:e4b</code> 404</td><td style="text-align:left;">systemd <code>lemond</code> ProtectHome hides user FLM cache; use 8219</td></tr><tr><td style="text-align:left;">Lemonade and <code>flm serve</code> fight over NPU</td><td style="text-align:left;"><code>lemonade unload</code> + stop <code>lemond</code>, or <code>pkill -x flm</code>; keep one client</td></tr><tr><td style="text-align:left;">503</td><td style="text-align:left;">NPU queue full; lower concurrency or raise <code>--q-len</code></td></tr><tr><td style="text-align:left;">OOM with a GPU model</td><td style="text-align:left;">unified memory; stop vLLM / Ollama / large GGUF first</td></tr><tr><td style="text-align:left;"><code>flm validate</code> fails in a sandbox</td><td style="text-align:left;">no <code>/dev/accel</code> is expected; run on a real terminal</td></tr></tbody></table>',3)])])}const u=e(n,[["render",a]]);export{g as __pageData,u as default};
